// Reading a configuration file line by line
public class ConfigLoader {
    public Map<String, String> loadConfig(Path configPath) throws IOException {
        var configMap = new HashMap<String, String>();

        // BufferedReader wraps FileReader for efficient line reading
        try (var reader = new BufferedReader(
                new FileReader(configPath.toFile(), StandardCharsets.UTF_8))) {

            String line;
            while ((line = reader.readLine()) != null) {  // null signals end of file
                if (line.startsWith("#") || line.isBlank()) continue;
                var parts = line.split("=", 2);
                configMap.put(parts[0].trim(), parts[1].trim());
            }
        }  // try-with-resources auto-closes the reader
        return configMap;
    }

    // Writing application logs with PrintWriter
    public void writeLog(String logPath, String message) throws IOException {
        try (var writer = new PrintWriter(
                new FileWriter(logPath, StandardCharsets.UTF_8, true))) {  // true = append mode
            writer.printf("[%s] %s%n", LocalDateTime.now(), message);
        }
    }
}

public class FileReadingExamples {

    // Traditional: line-by-line with full control
    public List<String> readWithBufferedReader(Path path) throws IOException {
        var result = new ArrayList<String>();
        try (var reader = new BufferedReader(
                new FileReader(path.toFile(), StandardCharsets.UTF_8))) {
            String line;
            while ((line = reader.readLine()) != null) {  // null = end of file
                if (!line.startsWith("#")) {
                    result.add(line.trim());
                }
            }
        }
        return result;
    }

    // Modern: Stream API for filtering and transformation
    public List<String> readWithStream(Path path) throws IOException {
        try (var lines = Files.lines(path, StandardCharsets.UTF_8)) {  // lazy stream
            return lines
                .filter(line -> !line.startsWith("#"))
                .map(String::trim)
                .filter(line -> !line.isEmpty())
                .toList();  // Java 17 convenience method
        }  // stream must be closed
    }

    // Simple: entire file at once (small files only)
    public List<String> readAllAtOnce(Path path) throws IOException {
        return Files.readAllLines(path, StandardCharsets.UTF_8);
    }
}

public class FileWritingExamples {

    // Simple: write entire string at once (Java 11+)
    public void saveConfig(Path configPath, String content) throws IOException {
        Files.writeString(configPath, content, StandardCharsets.UTF_8);
    }

    // Write list of lines (CSV export, filtered logs)
    public void exportOrders(Path outputPath, List<String> orderLines) throws IOException {
        Files.write(outputPath, orderLines, StandardCharsets.UTF_8);
    }

    // Append to log file (production logging)
    public void appendLog(Path logPath, String message) throws IOException {
        var logEntry = "[%s] %s%n".formatted(LocalDateTime.now(), message);
        Files.writeString(logPath, logEntry, StandardCharsets.UTF_8,
            StandardOpenOption.CREATE, StandardOpenOption.APPEND);  // append mode
    }

    // Incremental write with BufferedWriter (large reports)
    public void generateReport(Path reportPath, List<Order> orders) throws IOException {
        try (var writer = new BufferedWriter(
                new FileWriter(reportPath.toFile(), StandardCharsets.UTF_8))) {
            writer.write("Order Report\n");
            writer.write("=============\n");
            for (var order : orders) {
                writer.write("Order #%d: %s - $%.2f%n"
                    .formatted(order.id(), order.item(), order.amount()));
            }  // buffered writes, flushed on close
        }
    }
}

// Example 1: Servlet response (typical web usage)
public class OrderServlet extends HttpServlet {
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) 
            throws ServletException, IOException {
        resp.setContentType("text/html");
        var out = resp.getWriter();  // returns PrintWriter

        out.println("<html><body>");
        out.printf("<h1>Order #%d</h1>%n", 12345);
        out.printf("<p>Total: $%.2f</p>%n", 159.99);
        out.println("</body></html>");
        // No need to close - servlet container handles it
    }
}

// Example 2: Generating formatted reports to file
public class ReportGenerator {
    public void generateSalesReport(Path outputPath, List<Sale> sales) {
        try (var writer = new PrintWriter(
                new FileWriter(outputPath.toFile(), StandardCharsets.UTF_8))) {

            writer.println("Sales Report");
            writer.println("============");

            for (var sale : sales) {
                writer.printf("%-20s %10.2f %15s%n",  // aligned columns
                    sale.product(), sale.amount(), sale.date());
            }

            if (writer.checkError()) {  // explicit error check
                throw new IOException("Write failed - disk full or permission denied");
            }
        } catch (IOException e) {
            // Handle cleanup or logging
        }
    }
}

// Production code: report generator that writes to any Writer
public class InvoiceGenerator {
    public void generateInvoice(Writer output, Invoice invoice) throws IOException {
        var writer = new PrintWriter(output);  // wrap in PrintWriter for formatting
        writer.printf("Invoice #%d%n", invoice.id());
        writer.printf("Customer: %s%n", invoice.customer());
        writer.println("Items:");
        for (var item : invoice.items()) {
            writer.printf("  %s - $%.2f%n", item.name(), item.price());
        }
        writer.printf("Total: $%.2f%n", invoice.total());
        writer.flush();
    }
}

// Unit test: capture output with StringWriter
class InvoiceGeneratorTest {
    @Test
    void shouldGenerateCorrectInvoiceFormat() throws IOException {
        var invoice = new Invoice(123, "Acme Corp",
            List.of(new Item("Widget", 25.00), new Item("Gadget", 15.50)),
            40.50);

        var output = new StringWriter();  // in-memory capture
        var generator = new InvoiceGenerator();
        generator.generateInvoice(output, invoice);

        var result = output.toString();  // retrieve generated text
        assertThat(result)
            .contains("Invoice #123")
            .contains("Customer: Acme Corp")
            .contains("Widget - $25.00")
            .contains("Total: $40.50");
        // No file cleanup needed!
    }
}
